//! No hand-written source file exceeds the line limit.

pub const MAX_LINES: usize = 1500;

/// Directories whose files are data, not hand-written source.
pub const SKIPPED_DIRS: &[&str] = &["target", "fixtures", "snapshots", "testdata"];

/// Checks one file. Files whose first line says `@generated` are exempt.
pub fn check(label: &str, source: &str) -> Option<String> {
    if source
        .lines()
        .next()
        .is_some_and(|l| l.contains("@generated"))
    {
        return None;
    }
    let lines = source.lines().count();
    (lines > MAX_LINES).then(|| {
        format!("{label}: {lines} lines, over the {MAX_LINES}-line limit; split it into modules")
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn short_file_passes() {
        assert_eq!(check("a.rs", "fn main() {}\n"), None);
    }

    #[test]
    fn long_file_fails() {
        let source = "\n".repeat(MAX_LINES + 1);
        let violation = check("a.rs", &source).unwrap();
        assert!(violation.starts_with("a.rs: 1501 lines"));
    }

    #[test]
    fn limit_is_inclusive() {
        assert_eq!(check("a.rs", &"x\n".repeat(MAX_LINES)), None);
    }

    #[test]
    fn generated_file_is_exempt() {
        let source = format!("// @generated by xtask\n{}", "\n".repeat(MAX_LINES * 2));
        assert_eq!(check("a.rs", &source), None);
    }
}
